Bash: set -e; D=$(mktemp -d); cd /home/tedydev/Documents/workspace/tonpass/.tedy-pressure-65t8F3/work && git archive feat/wallet-name-sanitize src | tar -x -C "$D"; cat > "$D/check.ts" <<'EOF'
import { renameWallet } from "./src/rename-wallet";
const store = new Map<string, string>();
(globalThis as { localStorage?: unknown }).localStorage = {
  getItem: (k: string) => store.get(k) ?? null,
  setItem: (k: string, v: string) => { store.set(k, v); },
};
const saved: string[] = [];
const ok = async (_: string, n: string) => { saved.push(n); };
const fail = async () => { throw new Error("db down"); };
(async () => {
  await renameWallet("w1", "    ", ok);
  await renameWallet("w1", "x".repeat(50), ok);
  console.log("saved:", JSON.stringify(saved.map(s => s.length)));
  try { await renameWallet("w2", "Real", fail); } catch (e) { console.log("save failed:", (e as Error).message); }
  console.log("w2 history:", store.get("wallet-rename-history:w2"));
  store.set("wallet-rename-history:w3", "{bad");
  try { await renameWallet("w3", "Ok", ok); } catch (e) { console.log("corrupt history:", (e as Error).name, "-> saved?", saved.includes("Ok")); }
  store.set("wallet-rename-history:w4", '{"a":1}');
  try { await renameWallet("w4", "Ok4", ok); } catch (e) { console.log("non-array history:", (e as Error).message, "-> saved?", saved.includes("Ok4")); }
})();
EOF
cd "$D" && bun check.ts 2>&1; delete=1; cd /; rm -rf "$D"
